// Section: wire_class

class StrataCoreWire implements BaseWire {
  factory StrataCoreWire.fromExternalLibrary(ExternalLibrary lib) =>
      StrataCoreWire(lib.ffiDynamicLibrary);

  /// Holds the symbol lookup function.
  final ffi.Pointer<T> Function<T extends ffi.NativeType>(String symbolName)
  _lookup;

  /// The symbols are looked up in [dynamicLibrary].
  StrataCoreWire(ffi.DynamicLibrary dynamicLibrary)
    : _lookup = dynamicLibrary.lookup;
}
